from sympy import *
x,y,t,u,k,l,m,T=symbols('x y t u k lambda mu T')
ok=lambda c,mm: print(('OK  ' if c else 'BAD ')+mm)
ok(simplify((7*x+1)/((x+1)*(2*x-1))-(2/(x+1)+3/(2*x-1)))==0,'A0a')
v=integrate(2/(x+1)+3/(2*x-1),(x,1,2)); ok(simplify(v-(Rational(7,2)*log(3)-2*log(2)))==0,'A0b '+str(simplify(v)))
ok(simplify((3*x**2+9*x+7)/((x+1)*(x+2)**2)-(1/(x+1)+2/(x+2)-1/(x+2)**2))==0,'B0a')
v=integrate(1/(x+1)+2/(x+2)-1/(x+2)**2,(x,0,1)); ok(simplify(v-(2*log(3)-log(2)-Rational(1,6)))==0,'B0b '+str(simplify(v)))
s=series(sqrt(1+4*x),x,0,4).removeO(); ok(expand(s-(1+2*x-2*x**2+4*x**3))==0,'A1a')
ok(abs((1+0.02-0.0002+0.000004)-1.019804)<1e-12 and abs(5*1.019804-5.09902)<1e-6,'A1b √26≈%.5f true %.5f'%(5*1.019804,26**0.5))
s=series((2-x)**-2,x,0,4).removeO(); ok(expand(s-(Rational(1,4)+x/4+Rational(3,16)*x**2+x**3/8))==0,'B1a')
ok(series((1+3*x)/(2-x)**2,x,0,3).removeO().coeff(x,2)==Rational(15,16),'B1b 15/16')
X=t-1;Y=t**2+2*t; ok(expand(Y-((X)**2+4*X+3))==0,'A2a'); ok(diff(Y,t)/diff(X,t)==2*t+2,'A2b')
ok(solve(x**2+4*x+3-(3-x/4),x)==[-Rational(17,4),0] and (3+Rational(17,16))==Rational(65,16),'A2d (-17/4,65/16)')
X=3*cos(t);Y=2*sin(t); d=simplify(diff(Y,t)/diff(X,t)); ok(simplify(d+2*cos(t)/(3*sin(t)))==0,'B2b')
px,py=X.subs(t,pi/4),Y.subs(t,pi/4); ok(simplify(2*px+3*py-6*sqrt(2))==0 and simplify(d.subs(t,pi/4)+Rational(2,3))==0,'B2c 2x+3y=6√2')
ok(simplify(4*integrate(Y*diff(X,t),(t,pi/2,0)))==6*pi,'B2d 6π')
F=x**2+3*x*y+y**2-11; dy=-diff(F,x)/diff(F,y); ok(simplify(dy+(2*x+3*y)/(3*x+2*y))==0 and F.subs({x:1,y:2})==0 and dy.subs({x:1,y:2})==-Rational(8,7),'A3 a,b')
ok(solve(F.subs(x,-Rational(3,2)*y),y) and all(not z.is_real for z in solve(F.subs(x,-Rational(3,2)*y),y)),'A3c no real')
F=x**3+y**3-9*x*y; dy=-diff(F,x)/diff(F,y); ok(F.subs({x:2,y:4})==0 and dy.subs({x:2,y:4})==Rational(4,5),'B3 4/5')
ok(simplify(integrate(x*exp(2*x),x)-(x*exp(2*x)/2-exp(2*x)/4))==0,'A4a'); ok(simplify(integrate(x**2*log(x),(x,1,E))-(2*E**3+1)/9)==0,'A4b')
ok(integrate(x*sqrt(x+1),(x,0,3))==Rational(116,15) and integrate((u-1)*sqrt(u),(u,1,4))==Rational(116,15),'B4a 116/15')
ok(simplify(diff(-cos(x)**4/4,x)-sin(x)*cos(x)**3)==0,'B4b'); ok(integrate(sin(x)**2,(x,0,pi/2))==pi/4,'B4c π/4')
f=Function('f'); sol=dsolve(Eq(f(x).diff(x),2*x*f(x)**2),ics={f(0):1}); ok(simplify(sol.rhs-1/(1-x**2))==0,'A5 y=1/(1-x²)'); ok(sol.rhs.subs(x,Rational(1,2))==Rational(4,3),'A5b 4/3')
kk=log(2)/10; ok(simplify(20+70*exp(-kk*10)-55)==0,'B5b k=ln2/10'); tt=10*log(7)/log(2); ok(round(float(tt),1)==28.1 and simplify(20+70*exp(-kk*tt)-30)==0,'B5c t=%.3f'%float(tt))
s=solve([1+2*l-(2+m),2-l-(-1+2*m),-1+3*l-(3-m)],[l,m]); ok(s=={l:1,m:1},'A6a λ=μ=1 → (3,1,2)')
c=Rational(3)/sqrt(84); ok(round(float(acos(c)*180/pi),1)==70.9,'A6b %.3f'%float(acos(c)*180/pi))
A=Matrix([1,0,2]);B=Matrix([3,4,-2]);d=B-A; ok(d.norm()==6,'B6a |AB|=6')
tt=solve((A+t*d-Matrix([5,1,0])).dot(d),t)[0]; P=A+tt*d; ok(tt==Rational(5,9) and list(P)==[Rational(19,9),Rational(20,9),-Rational(2,9)],'B6c P')
ok(round(float((P-Matrix([5,1,0])).norm()),2)==3.14,'B6d %.4f'%float((P-Matrix([5,1,0])).norm()))
